From 6106e4a30226adddf30b46ff7bdc9b411f6f0219 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:54:29 +0100
Subject: [PATCH] applets/brightness: warn before Dark Mode replaces a
 customized look

The Dark Mode switch applied the other global theme right away, silently
replacing any color scheme, cursor or other setting the user had changed
from the current theme. Now it shows a warning with a Switch Anyway button.

BUG: 522868
---
 applets/brightness/DarkModeItem.qml           | 31 +++++++++++++++-
 applets/brightness/plugin/darkmodecontrol.cpp | 36 +++++++++++++++++++
 applets/brightness/plugin/darkmodecontrol.h   |  2 ++
 3 files changed, 68 insertions(+), 1 deletion(-)

diff --git a/applets/brightness/DarkModeItem.qml b/applets/brightness/DarkModeItem.qml
index 1b277d7a3..3f48795c1 100644
--- a/applets/brightness/DarkModeItem.qml
+++ b/applets/brightness/DarkModeItem.qml
@@ -75,7 +75,14 @@ PlasmaComponents3.ItemDelegate {
                     focusPolicy: Qt.NoFocus
                     text: i18nc("@action:button", "Dark Mode")
                     checked: DarkModeControl.darkMode
-                    onClicked: DarkModeControl.darkMode = checked
+                    onClicked: {
+                        if (DarkModeControl.lookModified()) {
+                            checked = Qt.binding(() => DarkModeControl.darkMode);
+                            modifiedMessage.visible = true;
+                        } else {
+                            DarkModeControl.darkMode = checked;
+                        }
+                    }
                 }

                 PlasmaComponents3.Button {
@@ -109,6 +116,28 @@ PlasmaComponents3.ItemDelegate {
                 wrapMode: Text.WordWrap
                 Layout.fillWidth: true
             }
+
+            Kirigami.InlineMessage {
+                id: modifiedMessage
+                Layout.fillWidth: true
+                type: Kirigami.MessageType.Warning
+                text: i18nc("@info", "Your changes to the current theme's colors, icons, cursors or other settings will be replaced by %1.", DarkModeControl.otherTheme)
+                showCloseButton: true
+                actions: Kirigami.Action {
+                    text: i18nc("@action:button", "Switch Anyway")
+                    onTriggered: {
+                        modifiedMessage.visible = false;
+                        DarkModeControl.darkMode = !DarkModeControl.darkMode;
+                    }
+                }
+
+                Connections {
+                    target: DarkModeControl
+                    function onDarkModeChanged() {
+                        modifiedMessage.visible = false;
+                    }
+                }
+            }
         }
     }
 }
diff --git a/applets/brightness/plugin/darkmodecontrol.cpp b/applets/brightness/plugin/darkmodecontrol.cpp
index b31274374..dbe08f25e 100644
--- a/applets/brightness/plugin/darkmodecontrol.cpp
+++ b/applets/brightness/plugin/darkmodecontrol.cpp
@@ -9,6 +9,7 @@
 #include <QLoggingCategory>
 #include <QProcess>

+#include <KConfigGroup>
 #include <KPackage/PackageLoader>

 #include "brightness_kdeglobalssettings.h"
@@ -79,6 +80,41 @@ void DarkModeControl::updateDarkMode()
     updateOtherTheme();
 }

+bool DarkModeControl::lookModified() const
+{
+    auto package = KPackage::PackageLoader::self()->loadPackage(u"Plasma/LookAndFeel"_s);
+    package.setPath(m_settings->lookAndFeelPackage());
+
+    const QString defaultsPath = package.filePath("defaults");
+    if (defaultsPath.isEmpty()) {
+        return false;
+    }
+
+    // The defaults file has groups like [kdeglobals][General], naming the config file first.
+    const KConfig defaults(defaultsPath, KConfig::SimpleConfig);
+    const QStringList fileNames = defaults.groupList();
+    for (const QString &fileName : fileNames) {
+        const KConfigGroup fileGroup = defaults.group(fileName);
+        const QStringList groupNames = fileGroup.groupList();
+        if (groupNames.isEmpty()) {
+            continue;
+        }
+
+        const KConfig config(fileName);
+        for (const QString &groupName : groupNames) {
+            const KConfigGroup group = config.group(groupName);
+            const QMap<QString, QString> entries = fileGroup.group(groupName).entryMap();
+            for (auto it = entries.cbegin(); it != entries.cend(); ++it) {
+                if (group.hasKey(it.key()) && group.readEntry(it.key()) != it.value()) {
+                    return true;
+                }
+            }
+        }
+    }
+
+    return false;
+}
+
 QString DarkModeControl::currentTheme() const
 {
     return m_currentTheme;
diff --git a/applets/brightness/plugin/darkmodecontrol.h b/applets/brightness/plugin/darkmodecontrol.h
index 32a718076..d8df9c195 100644
--- a/applets/brightness/plugin/darkmodecontrol.h
+++ b/applets/brightness/plugin/darkmodecontrol.h
@@ -32,6 +32,8 @@ public:
     void setDarkMode(bool enable);
     Q_SIGNAL void darkModeChanged();

+    Q_INVOKABLE bool lookModified() const;
+
     QString currentTheme() const;
     Q_SIGNAL void currentThemeChanged();

